function source(s, value) {
  text(s, value, 0.50, 6.86, 11.7, 0.15, { size: 7.3, color: s.dark ? 'AEB8C2' : C.soft, italic: true, valign: 'mid' });
}

function callout(s, value, x, y, w, h, opts = {}) {
  const fill = opts.fill || C.panel2;
  rect(s, x, y, w, h, fill, { radius: opts.radius || 0.12, stroke: opts.stroke || fill, strokeWidth: opts.strokeWidth || 0 });
  if (opts.accent) rect(s, x, y, 0.065, h, opts.accent, { radius: 0.02 });
  text(s, value, x + (opts.accent ? 0.20 : 0.16), y + 0.12, w - (opts.accent ? 0.32 : 0.30), h - 0.22, { size: opts.size || 14, bold: Boolean(opts.bold), color: opts.color || C.ink, valign: opts.valign || 'mid', align: opts.align || 'left', lineGap: opts.lineGap || 1.5 });
}

function modelLegend(s, x, y, keys = ['sol', 'glm', 'claude', 'deepseek'], opts = {}) {
  let dx = x;
  for (const key of keys) {
    circle(s, dx, y + 0.035, 0.11, MODELS[key].color);
    text(s, MODELS[key].name, dx + 0.16, y, opts.itemW || 0.78, 0.19, { size: opts.size || 9.8, color: opts.color || C.muted, valign: 'mid' });
    dx += opts.gap || 1.28;
  }
}

function sectionLabel(s, label, x, y, w, opts = {}) {
  text(s, label.toUpperCase(), x, y, w, 0.18, { size: opts.size || 9.2, bold: true, color: opts.color || C.crimson, valign: 'mid' });
}

function fmt(v, digits = 3) {
  return Number(v).toFixed(digits).replace(/^0/, '');
}

function average(values) {
  return values.reduce((a, b) => a + b, 0) / values.length;
}

function makeNotes(timing, takeaway, talk, question, answer) {
  return [
    `Timing: ${timing}`,
    `Takeaway: ${takeaway}`,
    '',
    `Talk track: ${talk}`,
    '',
    `Likely panel question: ${question}`,
    `Suggested answer: ${answer}`,
  ].join('\n');
}

