    const y = 1.75 + row * 0.92;
    rect(s, x, y, 5.82, 0.74, i % 2 === 0 ? C.crimsonLight : C.panel2, { radius: 0.10, stroke: i % 2 === 0 ? 'ECC7CE' : C.line, strokeWidth: 0.6 });
    circle(s, x + 0.22, y + 0.24, 0.20, i % 2 === 0 ? C.crimson : C.soft);
    text(s, String(i + 1), x + 0.22, y + 0.275, 0.20, 0.13, { size: 8.2, bold: true, color: C.white, align: 'center', valign: 'mid' });
    text(s, v, x + 0.57, y + 0.14, 4.92, 0.43, { size: 10.8, bold: true, color: C.ink, valign: 'mid' });
  });
  sectionLabel(s, 'Reproducibility artifacts', 0.62, 4.73, 2.4);
  rect(s, 0.62, 5.03, 12.08, 1.38, C.ink, { radius: 0.13 });
  const artifacts = [
    ['Frozen manifest', 'audit_manifests/direct_audit_full100...json'],
    ['Analysis', 'analyze_direct_audit.py · validate_proxy_evaluators.py'],
    ['Plot snapshot', 'analysis/slide_plots_20260825/plot_data.json'],
    ['Tests', 'local_soul_eval/tests/'],
  ];
  artifacts.forEach((a, i) => {
    const x = 0.91 + (i % 2) * 5.96;
    const y = 5.30 + Math.floor(i / 2) * 0.52;
    text(s, a[0].toUpperCase(), x, y, 1.24, 0.20, { size: 8.4, bold: true, color: 'E9AAB5', valign: 'mid' });
    text(s, a[1], x + 1.35, y, 4.31, 0.20, { size: 9.7, color: C.white, valign: 'mid' });
  });
  source(s, 'All slide claims are traceable to completed local artifacts; the stale top-level README/PROVENANCE wording was not used as current evidence.');
}

// ---------- Rendering ----------

function hex(color) {
  return `#${color}`;
}

function pptShapeType(pptx, obj) {
  if (obj.type === 'circle') return pptx.ShapeType.ellipse;
  if (obj.type === 'rect') return obj.radius > 0 ? pptx.ShapeType.roundRect : pptx.ShapeType.rect;
  return pptx.ShapeType.rect;
}

function renderPptxObject(pptx, slide, obj) {
  if (obj.type === 'rect') {
    slide.addShape(pptShapeType(pptx, obj), {
      x: obj.x, y: obj.y, w: obj.w, h: obj.h,
      fill: { color: obj.fill, transparency: obj.transparency || 0 },
      line: { color: obj.stroke || obj.fill, width: obj.strokeWidth || 0, transparency: obj.strokeWidth ? 0 : 100 },
      radius: obj.radius || 0,
    });
  } else if (obj.type === 'circle') {
    slide.addShape(pptx.ShapeType.ellipse, {
      x: obj.x, y: obj.y, w: obj.d, h: obj.d,
      fill: { color: obj.fill },
      line: { color: obj.stroke || obj.fill, width: obj.strokeWidth || 0, transparency: obj.strokeWidth ? 0 : 100 },
    });
  } else if (obj.type === 'line') {
    const dash = obj.dash === 'dash' ? 'dash' : 'solid';
    slide.addShape(pptx.ShapeType.line, {
      x: obj.x1, y: obj.y1, w: obj.x2 - obj.x1, h: obj.y2 - obj.y1,
      line: {
        color: obj.color, width: obj.width, dash,
        beginArrowType: obj.arrowStart ? 'triangle' : 'none',
        endArrowType: obj.arrowEnd ? 'triangle' : 'none',
      },
    });
  } else if (obj.type === 'text') {
    slide.addText(obj.value, {
      x: obj.x, y: obj.y, w: obj.w, h: obj.h,
      fontFace: FONT, fontSize: obj.size, color: obj.color,
      bold: obj.bold, italic: obj.italic,
      align: obj.align === 'center' ? 'center' : obj.align === 'right' ? 'right' : 'left',
      valign: obj.valign === 'mid' ? 'mid' : obj.valign === 'bottom' ? 'bottom' : 'top',
      margin: 0, breakLine: false, fit: 'shrink',
      transparency: Math.max(0, Math.min(100, Math.round((1 - obj.opacity) * 100))),
      lineSpacingMultiple: 1.0,
    });
  }
}

function renderPptx() {
  const pptx = new PptxGenJS();
  pptx.layout = 'LAYOUT_WIDE';
  pptx.author = 'Zidi Xiong';
  pptx.company = 'Harvard University';
  pptx.subject = 'Technical evaluation of user-simulator evaluators';
  pptx.title = 'Choosing a User-Simulator Evaluator';
  pptx.lang = 'en-US';
  pptx.theme = {
    headFontFace: FONT,
    bodyFontFace: FONT,
    lang: 'en-US',
  };
  pptx.defineSlideMaster({
    title: 'BLANK_WIDE',
    background: { color: C.paper },
    objects: [],
    slideNumber: { x: 12.42, y: 7.16, color: C.soft, fontFace: FONT, fontSize: 8 },
  });
  for (const s of slides) {
    const slide = pptx.addSlide();
    slide.background = { color: s.dark ? C.ink : C.paper };
    for (const obj of s.objects) renderPptxObject(pptx, slide, obj);
    slide.addNotes(s.notes);
  }
  return pptx.writeFile({ fileName: OUT_PPTX, compression: true });
}

function pdfTextOptions(obj) {
  return {
    width: obj.w * PT,
    height: obj.h * PT,
    align: obj.align === 'center' ? 'center' : obj.align === 'right' ? 'right' : 'left',
    lineGap: obj.lineGap,
    ellipsis: false,
  };
}

function renderPdfObject(doc, obj) {
  if (obj.type === 'rect') {
    doc.save();
    doc.opacity(1 - (obj.transparency || 0) / 100);
    if (obj.radius > 0) doc.roundedRect(obj.x * PT, obj.y * PT, obj.w * PT, obj.h * PT, obj.radius * PT);
    else doc.rect(obj.x * PT, obj.y * PT, obj.w * PT, obj.h * PT);
    doc.fillAndStroke(hex(obj.fill), obj.strokeWidth ? hex(obj.stroke) : hex(obj.fill));
    if (obj.strokeWidth) doc.lineWidth(obj.strokeWidth);
    doc.restore();
  } else if (obj.type === 'circle') {
    doc.save();
    doc.ellipse((obj.x + obj.d / 2) * PT, (obj.y + obj.d / 2) * PT, obj.d / 2 * PT, obj.d / 2 * PT);
    doc.fillAndStroke(hex(obj.fill), obj.strokeWidth ? hex(obj.stroke) : hex(obj.fill));
    if (obj.strokeWidth) doc.lineWidth(obj.strokeWidth);
    doc.restore();
  } else if (obj.type === 'line') {
    doc.save();
    doc.strokeColor(hex(obj.color)).lineWidth(obj.width).moveTo(obj.x1 * PT, obj.y1 * PT).lineTo(obj.x2 * PT, obj.y2 * PT).stroke();
    if (obj.arrowEnd) {
      const angle = Math.atan2(obj.y2 - obj.y1, obj.x2 - obj.x1);
      const len = 0.09 * PT;
      const x = obj.x2 * PT, y = obj.y2 * PT;
      doc.moveTo(x, y).lineTo(x - len * Math.cos(angle - 0.45), y - len * Math.sin(angle - 0.45)).lineTo(x - len * Math.cos(angle + 0.45), y - len * Math.sin(angle + 0.45)).fill(hex(obj.color));
    }
    doc.restore();
  } else if (obj.type === 'text') {
    doc.save();
    doc.opacity(obj.opacity);
    doc.font(obj.bold ? PDF_FONT_BOLD : PDF_FONT).fontSize(obj.size).fillColor(hex(obj.color));
    const opts = pdfTextOptions(obj);
    const measured = doc.heightOfString(obj.value, { width: opts.width, lineGap: obj.lineGap });
    let y = obj.y * PT;
    if (obj.valign === 'mid') y += Math.max(0, (obj.h * PT - measured) / 2);
    if (obj.valign === 'bottom') y += Math.max(0, obj.h * PT - measured);
    doc.text(obj.value, obj.x * PT, y, opts);
    doc.restore();
  }
}

function renderPdf() {
  return new Promise((resolve, reject) => {
    const doc = new PDFDocument({ autoFirstPage: false, size: [W * PT, H * PT], margin: 0, info: { Title: 'Choosing a User-Simulator Evaluator', Author: 'Zidi Xiong', Subject: 'Technical evaluation of user-simulator evaluators' } });
    const out = fs.createWriteStream(OUT_PDF);
    out.on('finish', resolve);
    out.on('error', reject);
    doc.pipe(out);
    for (const s of slides) {
      doc.addPage({ size: [W * PT, H * PT], margin: 0 });
      for (const obj of s.objects) renderPdfObject(doc, obj);
    }
    doc.end();
  });
}

function svgEscape(value) {
  return String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function svgText(obj) {
  const scale = PX;
  const size = obj.size * (scale / PT);
  const lines = obj.value.split('\n');
  const lineHeight = size * 1.18 + obj.lineGap * scale / PT;
  const total = lines.length * lineHeight;
  let y = obj.y * scale + size;
  if (obj.valign === 'mid') y = obj.y * scale + Math.max(size, (obj.h * scale - total) / 2 + size);
  if (obj.valign === 'bottom') y = (obj.y + obj.h) * scale - total + size;
  let x = obj.x * scale;
  let anchor = 'start';
  if (obj.align === 'center') { x += obj.w * scale / 2; anchor = 'middle'; }
  if (obj.align === 'right') { x += obj.w * scale; anchor = 'end'; }
  return `<text x="${x.toFixed(2)}" y="${y.toFixed(2)}" font-family="Nimbus Sans, Arial, sans-serif" font-size="${size.toFixed(2)}" font-weight="${obj.bold ? 700 : 400}" font-style="${obj.italic ? 'italic' : 'normal'}" fill="${hex(obj.color)}" opacity="${obj.opacity}" text-anchor="${anchor}">${lines.map((ln, i) => `<tspan x="${x.toFixed(2)}" dy="${i === 0 ? 0 : lineHeight.toFixed(2)}">${svgEscape(ln)}</tspan>`).join('')}</text>`;
}

function renderSvgObject(obj) {
  const S = PX;
  if (obj.type === 'rect') {
    return `<rect x="${(obj.x*S).toFixed(2)}" y="${(obj.y*S).toFixed(2)}" width="${(obj.w*S).toFixed(2)}" height="${(obj.h*S).toFixed(2)}" rx="${(obj.radius*S).toFixed(2)}" fill="${hex(obj.fill)}" fill-opacity="${1-(obj.transparency||0)/100}" stroke="${obj.strokeWidth ? hex(obj.stroke) : 'none'}" stroke-width="${obj.strokeWidth}"/>`;
  }
  if (obj.type === 'circle') {
    return `<circle cx="${((obj.x+obj.d/2)*S).toFixed(2)}" cy="${((obj.y+obj.d/2)*S).toFixed(2)}" r="${(obj.d*S/2).toFixed(2)}" fill="${hex(obj.fill)}" stroke="${obj.strokeWidth ? hex(obj.stroke) : 'none'}" stroke-width="${obj.strokeWidth}"/>`;
  }
  if (obj.type === 'line') {
    return `<line x1="${(obj.x1*S).toFixed(2)}" y1="${(obj.y1*S).toFixed(2)}" x2="${(obj.x2*S).toFixed(2)}" y2="${(obj.y2*S).toFixed(2)}" stroke="${hex(obj.color)}" stroke-width="${obj.width}" ${obj.dash ? 'stroke-dasharray="8 6"' : ''}/>`;
  }
  if (obj.type === 'text') return svgText(obj);
  return '';
}

function renderSvgs() {
  for (const s of slides) {
    const svg = `<?xml version="1.0" encoding="UTF-8"?>\n<svg xmlns="http://www.w3.org/2000/svg" width="1600" height="900" viewBox="0 0 1600 900">\n${s.objects.map(renderSvgObject).join('\n')}\n</svg>\n`;
    fs.writeFileSync(path.join(RENDER_DIR, `slide-${String(s.number).padStart(2, '0')}.svg`), svg);
  }
}

async function main() {
  renderSvgs();
  await Promise.all([renderPptx(), renderPdf()]);
  console.log(JSON.stringify({ slides: slides.length, pptx: OUT_PPTX, pdf: OUT_PDF, svgDir: RENDER_DIR }, null, 2));
}

main().catch(err => {
  console.error(err.stack || err);
  process.exit(1);
});

